void Solver::bump_var(int var, double coeff) {
    constexpr double ACT_LIMIT   = 1e100;
    constexpr double RESCALE_FAC = 1e-100;

    // keep a running maximum of activity to avoid scanning all vars each call
    static double cur_max = 0.0;

    double inc = var_inc * coeff;
    activity[var] += inc;

    // update the running maximum
    if (activity[var] > cur_max) cur_max = activity[var];

    // if any activity exceeds safe limit, rescale everything once
    if (cur_max > ACT_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FAC;
        var_inc *= RESCALE_FAC;
        cur_max *= RESCALE_FAC;   // the maximum also gets scaled
    }

    // keep the VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
